    const input=document.querySelector('[data-ph]');if(input&&d.search){input.placeholder=d.search;input.setAttribute('aria-label',d.search);}
    const cards=document.querySelector('.home-cards');if(cards){const labels={en:['Product categories','Product details','SEO articles','FAQ','Latest content'],de:['Produktkategorien','Produktdetails','SEO-Artikel','FAQ','Neueste Inhalte'],fr:['Catégories produit','Détails produit','Articles SEO','FAQ','Dernier contenu'],es:['Categorías de productos','Detalles del producto','Artículos SEO','FAQ','Contenido reciente'],it:['Categorie prodotto','Dettagli prodotto','Articoli SEO','FAQ','Contenuti recenti'],pt:['Categorias de produtos','Detalhes do produto','Artigos SEO','FAQ','Conteúdo recente'],nl:['Productcategorieën','Productdetails','SEO-artikelen','FAQ','Nieuwste inhoud'],pl:['Kategorie produktów','Szczegóły produktu','Artykuły SEO','FAQ','Najnowsze treści']}[lang]||[];cards.querySelectorAll('a').forEach((a,i)=>{const sm=a.querySelector('small');a.textContent='';if(sm)a.append(sm);a.append(document.createTextNode(labels[i]||''));});}
